package com.sih.analytics.controller; import com.sih.analytics.dto.AnalyticsDtos.*; import com.sih.analytics.service.*; import jakarta.validation.*; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/analytics") public class AnalyticsController{final AnalyticsService s;public AnalyticsController(AnalyticsService s){this.s=s;}@GetMapping("/metrics")List<MetricResponse>l(){return s.list();}@PostMapping("/metrics")@ResponseStatus(HttpStatus.CREATED)MetricResponse c(@Valid @RequestBody MetricRequest r){return s.record(r);}@GetMapping("/dashboard")DashboardResponse d(){return s.dashboard();}}